package main

import "fmt"

// ❌ OLD: Storing an int in an interface (any) escapes to the heap:
// the interface header's data word points to a heap-allocated copy.
// In a hot loop, this allocates per iteration (GC pressure).
func printAll(n int) {
	for i := 0; i < n; i++ {
		var v any = i // ❌ OLD: i escapes to the heap each iteration
		fmt.Println(v)
	}
}

// Check: go build -gcflags='-m'  →  "i escapes to heap"
// The escape happens because the interface value can outlive the
// function (fmt.Println stores it), so the compiler must heap-allocate.

