package main

// ✅ NEW: Concrete local values that don't escape are stack-allocated:
// no heap, no GC pressure, allocation-free execution.
func sum(n int) int {
	var total int // ✅ NEW: does not escape → stack slot
	for i := 0; i < n; i++ {
		total += i
	}
	return total // ✅ NEW: an int return value doesn't escape
}

// ✅ NEW: Returning a pointer to a small struct:
func newPoint(x, y int) *Point {
	p := Point{x, y} // ❓ escapes: the pointer is returned
	return &p
}
// The compiler MAY still stack-allocate if the caller's use allows it
// (e.g. the pointer is only used within the same function via
// inlining). Verify with: go build -gcflags='-m'.

// In general: prefer value receivers and concrete types on hot paths;
// interfaces and returned pointers tend to force heap allocation.
